function isValidHolidayDate(string $date): bool {
    $parsed = DateTime::createFromFormat('!Y-m-d', $date);
    $errors = DateTime::getLastErrors();
    return $parsed && $parsed->format('Y-m-d') === $date && ($errors === false || ($errors['warning_count'] === 0 && $errors['error_count'] === 0));
}

function logHolidayActivity(PDO $pdo, string $action, string $description): void {
    try {
        $pdo->prepare('INSERT INTO activity_logs (user_id, action, description) VALUES (?, ?, ?)')
            ->execute([(int)$_SESSION['user_id'], $action, $description]);
    } catch (PDOException $ignored) {
    }
}

$action = $_GET['action'] ?? $_POST['action'] ?? '';
if ($action) {
    header('Content-Type: application/json');
    if ($_SERVER['REQUEST_METHOD'] === 'POST') { csrf_verify(true); }

    try {
        switch ($action) {
            case 'list':
                $search = trim($_GET['search'] ?? '');
                $where = '';
                $params = [];
                if ($search !== '') {
                    $where = 'WHERE holiday_date LIKE ? OR description LIKE ?';
                    $term = '%' . $search . '%';
                    $params = [$term, $term];
                }
                $stmt = $pdo->prepare("SELECT holiday_id, holiday_date, description, is_recurring, created_at
                    FROM holidays $where
                    ORDER BY MONTH(holiday_date), DAY(holiday_date), is_recurring DESC, holiday_date DESC, description ASC");
                $stmt->execute($params);
                $stats = $pdo->query('SELECT COUNT(*) AS total, SUM(is_recurring = 1) AS recurring, SUM(is_recurring = 0) AS one_time FROM holidays')->fetch();
                echo json_encode(['success' => true, 'data' => $stmt->fetchAll(), 'stats' => $stats]);
                break;

            case 'get':
                $id = (int)($_GET['id'] ?? 0);
                $stmt = $pdo->prepare('SELECT holiday_id, holiday_date, description, is_recurring FROM holidays WHERE holiday_id = ?');
                $stmt->execute([$id]);
                $holiday = $stmt->fetch();
                echo json_encode($holiday ? ['success' => true, 'data' => $holiday] : ['success' => false, 'message' => 'Holiday not found.']);
                break;

            case 'save':
                $id = (int)($_POST['holiday_id'] ?? 0);
                $date = trim($_POST['holiday_date'] ?? '');
                $description = trim($_POST['description'] ?? '');
                $isRecurring = isset($_POST['is_recurring']) ? 1 : 0;

                if (!isValidHolidayDate($date) || $description === '') {
                    echo json_encode(['success' => false, 'message' => 'A valid holiday date and description are required.']);
                    break;
                }
                if (mb_strlen($description) > 255) {
                    echo json_encode(['success' => false, 'message' => 'The description must not exceed 255 characters.']);
                    break;
                }

                $duplicate = $pdo->prepare('SELECT holiday_id FROM holidays WHERE holiday_date = ? AND holiday_id != ?');
                $duplicate->execute([$date, $id]);
                if ($duplicate->fetch()) {
                    echo json_encode(['success' => false, 'message' => 'Another holiday already uses that date.']);
                    break;
                }

                if ($id) {
                    $pdo->prepare('UPDATE holidays SET holiday_date = ?, description = ?, is_recurring = ? WHERE holiday_id = ?')
                        ->execute([$date, $description, $isRecurring, $id]);
                    logHolidayActivity($pdo, 'UPDATE_HOLIDAY', "Updated holiday #$id: $description ($date)");
                    echo json_encode(['success' => true, 'message' => 'Holiday updated.']);
                } else {
                    $pdo->prepare('INSERT INTO holidays (holiday_date, description, is_recurring) VALUES (?, ?, ?)')
                        ->execute([$date, $description, $isRecurring]);
                    $holidayId = (int)$pdo->lastInsertId();
                    logHolidayActivity($pdo, 'ADD_HOLIDAY', "Added holiday #$holidayId: $description ($date)");
                    echo json_encode(['success' => true, 'message' => 'Holiday added.']);
                }
                break;

            case 'delete':
                $id = (int)($_POST['id'] ?? 0);
                $stmt = $pdo->prepare('SELECT holiday_date, description FROM holidays WHERE holiday_id = ?');
                $stmt->execute([$id]);
                $holiday = $stmt->fetch();
                if (!$holiday) {
                    echo json_encode(['success' => false, 'message' => 'Holiday not found.']);
                    break;
                }
                $pdo->prepare('DELETE FROM holidays WHERE holiday_id = ?')->execute([$id]);
                logHolidayActivity($pdo, 'DELETE_HOLIDAY', "Deleted holiday #$id: {$holiday['description']} ({$holiday['holiday_date']})");
                echo json_encode(['success' => true, 'message' => 'Holiday deleted. Existing leave requests were not changed.']);
                break;

            default:
                echo json_encode(['success' => false, 'message' => 'Unknown action.']);
        }
    } catch (PDOException $exception) {
        error_log('[HRMS] holidays.php: ' . $exception->getMessage());
        echo json_encode(['success' => false, 'message' => 'A database error occurred.']);
    }
    exit();
}

$notifCount = 0;
$notifications = [];
try {
    $pendingRequests = $pdo->query("SELECT lr.request_id, CONCAT(e.first_name, ' ', e.last_name) AS employee_name, lt.name AS leave_type, lr.days_requested, lr.filed_at
        FROM leave_requests lr
        JOIN employees e ON e.employee_id = lr.employee_id
        JOIN leave_types lt ON lt.leave_type_id = lr.leave_type_id
        WHERE lr.status = 'Pending' AND lr.is_deleted = 0
        ORDER BY lr.filed_at DESC LIMIT 10")->fetchAll();
    foreach ($pendingRequests as $request) {
        $notifications[] = ['icon' => '📋', 'color' => '#f59e0b', 'title' => 'Leave Request', 'body' => $request['employee_name'] . ' filed ' . (int)$request['days_requested'] . ' day(s) of ' . $request['leave_type'], 'time' => $request['filed_at'], 'link' => 'leave_requests.php'];
    }
    try {
        $expiringContracts = $pdo->query("SELECT CONCAT(e.first_name, ' ', e.last_name) AS employee_name, DATEDIFF(c.end_date, CURDATE()) AS days_left
            FROM contracts c JOIN employees e ON e.employee_id = c.employee_id
            WHERE c.status = 'Active' AND c.end_date IS NOT NULL AND DATEDIFF(c.end_date, CURDATE()) BETWEEN 0 AND 30
            ORDER BY c.end_date ASC LIMIT 5")->fetchAll();
        foreach ($expiringContracts as $contract) {
            $daysLeft = (int)$contract['days_left'];
            $notifications[] = ['icon' => '📝', 'color' => '#ef4444', 'title' => 'Contract Expiring', 'body' => $contract['employee_name'] . "'s contract expires in $daysLeft day" . ($daysLeft === 1 ? '' : 's'), 'time' => null, 'link' => 'contracts.php'];
        }
    } catch (PDOException $ignored) {
    }
    $notifCount = count($notifications);
} catch (PDOException $ignored) {
}

