<div class="modal-layer" id="holidayModal" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><div class="modal"><div class="modal-header"><h2 id="modalTitle">Add Holiday</h2><button class="icon-button" type="button" aria-label="Close" onclick="closeModal()">×</button></div><div class="modal-body"><input id="holidayId" type="hidden"><div class="field"><label for="holidayDate">Date</label><input id="holidayDate" type="date" required></div><div class="field"><label for="holidayDescription">Description</label><textarea id="holidayDescription" maxlength="255" placeholder="e.g. Independence Day" required></textarea></div><label class="check-row"><input id="holidayRecurring" type="checkbox"><span><strong>Repeats annually</strong><br>Use for fixed dates such as June 12. Leave this off for special or proclamation-based holidays.</span></label></div><div class="modal-footer"><button class="button ghost" type="button" onclick="closeModal()">Cancel</button><button class="button primary" id="saveButton" type="button" onclick="saveHoliday()">Save Holiday</button></div></div></div>
<div class="modal-layer" id="deleteModal" role="dialog" aria-modal="true" aria-labelledby="deleteTitle"><div class="modal"><div class="modal-header"><h2 id="deleteTitle">Delete Holiday</h2><button class="icon-button" type="button" aria-label="Close" onclick="closeDelete()">×</button></div><div class="modal-body"><p id="deleteText">Delete this holiday?</p><p style="color:var(--muted);font-size:.84rem">Existing leave requests and balances will not be recalculated.</p></div><div class="modal-footer"><button class="button ghost" type="button" onclick="closeDelete()">Cancel</button><button class="button danger" id="deleteButton" type="button" onclick="deleteHoliday()">Delete</button></div></div></div>
<section class="chat-drawer" id="chatDrawer"><header class="chat-widget-header"><div class="chat-widget-title"><div class="chat-widget-icon">💬</div><div><strong>Messages</strong><span id="chatWidgetSubtitle">Select someone to chat</span></div></div><button class="chat-close" type="button" title="Close" onclick="toggleChat()">×</button></header><div class="cw-body"><aside class="cw-contacts"><div class="cw-contacts-hd">Employees</div><div class="cw-srch"><input id="cwSearch" type="search" placeholder="🔍 Search..." oninput="filterChatContacts()"></div><div class="cw-clist" id="chatContacts"><div class="cw-cempty">Loading...</div></div></aside><div class="cw-chat"><div class="cw-nosel" id="cwNoSel"><div class="cw-nosel-ic">💬</div><h4>No conversation selected</h4><p>Pick an employee from<br>the list to start chatting</p></div><div id="cwChatArea" style="display:none;flex:1;flex-direction:column;overflow:hidden"><div class="cw-chat-hd"><div class="cw-chat-av" id="cwChatAvatar"></div><div style="flex:1;min-width:0"><div class="cw-chat-name" id="cwChatName"></div><div class="cw-chat-sub" id="cwChatSub"></div></div><button class="cw-chat-del" id="cwChatDelete" type="button" title="Delete conversation" onclick="deleteChatConversation()">🗑️</button><div class="cw-online" title="Active"></div></div><div class="cw-msgs" id="chatMessages"></div><div class="cw-edit-bar" id="cwEditBar">✏️ Editing message <button class="cw-edit-cancel" type="button" onclick="cancelChatEdit()">✕ Cancel</button></div><form class="cw-inp-row" id="chatForm" onsubmit="sendChat(event)"><input class="cw-inp" id="chatInput" type="text" maxlength="2000" placeholder="Type a message..." disabled><button class="cw-sendbtn" id="chatSend" type="submit" title="Send" disabled>➜</button></form></div></div></div></section>
<script>
const CSRF_TOKEN = document.querySelector('meta[name=csrf-token]').content;
let debounceTimer; let deleteTarget = null;
function escapeHtml(value) { const element = document.createElement('div'); element.textContent = value ?? ''; return element.innerHTML; }
function formatDate(value) { return value ? new Date(`${value}T00:00:00`).toLocaleDateString('en-PH', {month:'short', day:'numeric', year:'numeric'}) : ''; }
function queueLoad() { clearTimeout(debounceTimer); debounceTimer = setTimeout(loadHolidays, 250); }
async function loadHolidays() {
  const search = document.getElementById('searchInput').value.trim();
  try {
    const response = await fetch(`holidays.php?action=list&search=${encodeURIComponent(search)}`); const json = await response.json();
    if (!json.success) { showToast(json.message || 'Unable to load holidays.', 'error'); return; }
    document.getElementById('totalStat').textContent = json.stats.total || 0; document.getElementById('recurringStat').textContent = json.stats.recurring || 0; document.getElementById('oneTimeStat').textContent = json.stats.one_time || 0;
    const rows = document.getElementById('holidayRows');
    rows.innerHTML = json.data.length ? json.data.map(holiday => `<tr><td>${formatDate(holiday.holiday_date)}</td><td class="holiday-name">${escapeHtml(holiday.description)}</td><td><span class="badge ${Number(holiday.is_recurring) ? 'recurring' : 'once'}">${Number(holiday.is_recurring) ? 'Every year' : 'One time'}</span></td><td>${formatDate(holiday.created_at)}</td><td><div class="actions"><button class="icon-button" type="button" title="Edit holiday" onclick="openEdit(${Number(holiday.holiday_id)})">✎</button><button class="icon-button delete" type="button" title="Delete holiday" onclick="openDelete(${Number(holiday.holiday_id)})">×</button></div></td></tr>`).join('') : '<tr><td colspan="5" class="empty">No holidays found.</td></tr>';
  } catch (error) { showToast('Unable to load holidays.', 'error'); }
}
function openAdd() { document.getElementById('holidayId').value = ''; document.getElementById('holidayDate').value = ''; document.getElementById('holidayDescription').value = ''; document.getElementById('holidayRecurring').checked = false; document.getElementById('modalTitle').textContent = 'Add Holiday'; document.getElementById('saveButton').textContent = 'Save Holiday'; document.getElementById('holidayModal').classList.add('open'); }
async function openEdit(id) { try { const response = await fetch(`holidays.php?action=get&id=${id}`); const json = await response.json(); if (!json.success) { showToast(json.message, 'error'); return; } const holiday = json.data; document.getElementById('holidayId').value = holiday.holiday_id; document.getElementById('holidayDate').value = holiday.holiday_date; document.getElementById('holidayDescription').value = holiday.description; document.getElementById('holidayRecurring').checked = Number(holiday.is_recurring) === 1; document.getElementById('modalTitle').textContent = 'Edit Holiday'; document.getElementById('saveButton').textContent = 'Update Holiday'; document.getElementById('holidayModal').classList.add('open'); } catch (error) { showToast('Unable to load holiday.', 'error'); } }
function closeModal() { document.getElementById('holidayModal').classList.remove('open'); }
async function saveHoliday() { const date = document.getElementById('holidayDate').value; const description = document.getElementById('holidayDescription').value.trim(); if (!date || !description) { showToast('Date and description are required.', 'error'); return; } const button = document.getElementById('saveButton'); button.disabled = true; const body = new FormData(); body.append('action', 'save'); body.append('holiday_id', document.getElementById('holidayId').value); body.append('holiday_date', date); body.append('description', description); if (document.getElementById('holidayRecurring').checked) body.append('is_recurring', '1'); body.append('csrf_token', CSRF_TOKEN); try { const response = await fetch('holidays.php', {method:'POST', body}); const json = await response.json(); if (!json.success) { showToast(json.message, 'error'); return; } closeModal(); showToast(json.message, 'success'); loadHolidays(); } catch (error) { showToast('Unable to save holiday.', 'error'); } finally { button.disabled = false; } }
function openDelete(id) { deleteTarget = id; document.getElementById('deleteText').textContent = 'Delete this holiday?'; document.getElementById('deleteModal').classList.add('open'); }
function closeDelete() { document.getElementById('deleteModal').classList.remove('open'); deleteTarget = null; }
async function deleteHoliday() { if (!deleteTarget) return; const button = document.getElementById('deleteButton'); button.disabled = true; const body = new FormData(); body.append('action', 'delete'); body.append('id', deleteTarget); body.append('csrf_token', CSRF_TOKEN); try { const response = await fetch('holidays.php', {method:'POST', body}); const json = await response.json(); if (!json.success) { showToast(json.message, 'error'); return; } closeDelete(); showToast(json.message, 'success'); loadHolidays(); } catch (error) { showToast('Unable to delete holiday.', 'error'); } finally { button.disabled = false; } }
function showToast(message, type) { document.querySelectorAll('.toast').forEach(node => node.remove()); const toast = document.createElement('div'); toast.className = `toast ${type}`; toast.textContent = message; document.body.appendChild(toast); setTimeout(() => toast.remove(), 3500); }
const NOTIF_STORAGE_KEY = 'hrms_admin_read_notifs';
function getReadNotifs() { try { return JSON.parse(localStorage.getItem(NOTIF_STORAGE_KEY) || '[]'); } catch (error) { return []; } }
function saveReadNotifs(ids) { try { localStorage.setItem(NOTIF_STORAGE_KEY, JSON.stringify(ids.slice(-200))); } catch (error) {} }
function markNotifRead(id) { const read = getReadNotifs(); if (id && !read.includes(id)) { read.push(id); saveReadNotifs(read); } }
function applyReadState() { const read = getReadNotifs(); let unread = 0; document.querySelectorAll('.notif-item[data-nid]').forEach(item => { if (read.includes(item.dataset.nid)) item.classList.remove('unread'); else unread++; }); const count = document.getElementById('adminNotifCount'); if (count) { count.textContent = unread || ''; count.classList.toggle('show', unread > 0); } }
function clearNotifications() { const read = getReadNotifs(); document.querySelectorAll('.notif-item[data-nid]').forEach(item => { if (!read.includes(item.dataset.nid)) read.push(item.dataset.nid); }); saveReadNotifs(read); applyReadState(); document.getElementById('adminNotifPanel').classList.remove('open'); }
function toggleNotifPanel() { const panel = document.getElementById('adminNotifPanel'); document.getElementById('tbDropdown').classList.remove('open'); panel.classList.toggle('open'); if (panel.classList.contains('open')) applyReadState(); }
function toggleProfileDropdown() { document.getElementById('adminNotifPanel').classList.remove('open'); document.getElementById('tbDropdown').classList.toggle('open'); }
let chatContacts = []; let activeChat = null; let chatMessages = []; let editingMessageId = null; const CHAT_API = 'chat_api.php'; const CHAT_ME = <?= (int)$_SESSION['user_id'] ?>;
function escapeChat(value) { return escapeHtml(value).replace(/\n/g, '<br>'); }
function chatInitials(name) { return String(name || '?').split(' ').map(part => part.charAt(0)).join('').slice(0, 2).toUpperCase(); }
function chatColor(name) { const colors = ['#2563eb','#22c55e','#f59e0b','#ef4444','#a855f7','#06b6d4']; return colors[Math.abs([...String(name || '?')].reduce((sum, character) => sum + character.charCodeAt(0), 0)) % colors.length]; }
async function toggleChat() { const drawer = document.getElementById('chatDrawer'); drawer.classList.toggle('open'); if (drawer.classList.contains('open')) await loadChatContacts(); }
function renderChatContacts(contacts) { const list = document.getElementById('chatContacts'); list.innerHTML = contacts.length ? contacts.map(contact => { const name = contact.full_name || contact.email; const isActive = activeChat && Number(activeChat.user_id) === Number(contact.user_id); return `<div class="cw-ci ${isActive ? 'active' : ''}" role="button" tabindex="0" onclick="openChat(${Number(contact.user_id)})"><div class="cw-av" style="background:${chatColor(name)}">${chatInitials(name)}</div><div class="cw-cn" title="${escapeHtml(name)}">${escapeHtml(name)}</div><div class="cw-cs">${escapeHtml(contact.last_message || contact.position_title || '')}</div>${Number(contact.unread) ? `<div class="cw-cu">${Number(contact.unread)}</div>` : ''}</div>`; }).join('') : '<div class="cw-cempty">No employees found.</div>'; }
function filterChatContacts() { const query = document.getElementById('cwSearch').value.trim().toLowerCase(); renderChatContacts(chatContacts.filter(contact => `${contact.full_name || ''} ${contact.email || ''}`.toLowerCase().includes(query))); }
async function loadChatContacts() { try { const response = await fetch(`${CHAT_API}?action=contacts`); const json = await response.json(); if (!json.success) return; chatContacts = json.data; const unread = chatContacts.reduce((total, contact) => total + Number(contact.unread || 0), 0); const badge = document.getElementById('cwBadge'); badge.textContent = unread || ''; badge.style.display = unread ? 'flex' : 'none'; filterChatContacts(); } catch (error) {} }
async function openChat(userId) { activeChat = chatContacts.find(contact => Number(contact.user_id) === userId); if (!activeChat) return; const name = activeChat.full_name || activeChat.email; document.getElementById('chatWidgetSubtitle').textContent = name; document.getElementById('cwNoSel').style.display = 'none'; document.getElementById('cwChatArea').style.display = 'flex'; document.getElementById('cwChatAvatar').textContent = chatInitials(name); document.getElementById('cwChatAvatar').style.background = chatColor(name); document.getElementById('cwChatName').textContent = name; document.getElementById('cwChatSub').textContent = activeChat.position_title || 'Employee'; document.getElementById('cwChatDelete').style.display = 'flex'; document.getElementById('chatInput').disabled = false; document.getElementById('chatSend').disabled = false; await loadMessages(); filterChatContacts(); }
async function loadMessages() { if (!activeChat) return; try { const response = await fetch(`${CHAT_API}?action=messages&with=${Number(activeChat.user_id)}`); const json = await response.json(); if (!json.success) return; chatMessages = json.data; const messages = document.getElementById('chatMessages'); messages.innerHTML = chatMessages.length ? chatMessages.map(message => { const mine = Number(message.sender_id) === CHAT_ME; const unsent = Number(message.is_unsent) === 1; const senderName = mine ? 'You' : (activeChat.full_name || activeChat.email); const actions = mine && !unsent ? `<div class="cw-msg-actions"><button class="cw-act-btn" type="button" title="Edit message" onclick="startChatEdit(${Number(message.message_id)})">✏️</button><button class="cw-act-btn del" type="button" title="Unsend message" onclick="unsendChatMessage(${Number(message.message_id)})">🗑️</button></div>` : ''; const bubbleClasses = `cw-bubble ${unsent ? 'unsent' : (Number(message.is_edited) ? 'edited' : '')}`; return `<div class="cw-mrow ${mine ? 'mine' : 'them'}">${actions}${mine ? '' : `<div class="cw-mav" style="background:${chatColor(senderName)}">${chatInitials(senderName)}</div>`}<div class="cw-msg-wrap"><div class="${bubbleClasses}">${unsent ? 'You unsent a message' : escapeChat(message.message)}</div><div class="cw-mt">${new Date(message.sent_at).toLocaleTimeString('en-PH',{hour:'numeric',minute:'2-digit'})}${mine ? ' ✓✓ Seen' : ''}</div></div></div>`; }).join('') : '<div class="chat-placeholder">No messages yet.</div>'; messages.scrollTop = messages.scrollHeight; } catch (error) {} }
async function deleteChatConversation() { if (!activeChat) return; const name = activeChat.full_name || activeChat.email; if (!confirm(`Delete the entire conversation with ${name}? This cannot be undone.`)) return; const button = document.getElementById('cwChatDelete'); button.disabled = true; const body = new FormData(); body.append('action', 'delete_conversation'); body.append('with', activeChat.user_id); body.append('csrf_token', CSRF_TOKEN); try { const response = await fetch(CHAT_API, {method:'POST', body}); const json = await response.json(); if (!json.success) { showToast(json.message || 'Unable to delete conversation.', 'error'); return; } activeChat = null; document.getElementById('chatWidgetSubtitle').textContent = 'Select someone to chat'; document.getElementById('cwChatArea').style.display = 'none'; document.getElementById('cwNoSel').style.display = 'flex'; document.getElementById('cwChatDelete').style.display = 'none'; document.getElementById('chatInput').value = ''; document.getElementById('chatInput').disabled = true; document.getElementById('chatSend').disabled = true; showToast('Conversation deleted.', 'success'); await loadChatContacts(); } catch (error) { showToast('Unable to delete conversation.', 'error'); } finally { button.disabled = false; } }
function startChatEdit(messageId) { const message = chatMessages.find(item => Number(item.message_id) === messageId); if (!message) return; editingMessageId = messageId; const input = document.getElementById('chatInput'); input.value = message.message; input.focus(); document.getElementById('cwEditBar').classList.add('show'); document.getElementById('chatSend').textContent = '✓'; }
function cancelChatEdit() { editingMessageId = null; document.getElementById('chatInput').value = ''; document.getElementById('cwEditBar').classList.remove('show'); document.getElementById('chatSend').textContent = '➜'; }
async function unsendChatMessage(messageId) { if (!confirm('Unsend this message? It will be removed for everyone.')) return; const body = new FormData(); body.append('action', 'unsend'); body.append('message_id', messageId); body.append('csrf_token', CSRF_TOKEN); try { const response = await fetch(CHAT_API, {method:'POST', body}); const json = await response.json(); if (!json.success) { showToast(json.message || 'Unable to unsend message.', 'error'); return; } await loadMessages(); loadChatContacts(); } catch (error) { showToast('Unable to unsend message.', 'error'); } }
async function sendChat(event) { event.preventDefault(); if (!activeChat) return; const input = document.getElementById('chatInput'); const message = input.value.trim(); if (!message) return; const body = new FormData(); body.append('action', editingMessageId ? 'edit' : 'send'); body.append(editingMessageId ? 'message_id' : 'to', editingMessageId || activeChat.user_id); body.append('message', message); body.append('csrf_token', CSRF_TOKEN); try { const response = await fetch(CHAT_API, {method:'POST', body}); const json = await response.json(); if (!json.success) { showToast(json.message || 'Unable to save message.', 'error'); return; } cancelChatEdit(); await loadMessages(); loadChatContacts(); } catch (error) { showToast('Unable to save message.', 'error'); } }
document.addEventListener('click', event => { const notifications = document.getElementById('adminNotifWrap'); if (notifications && !notifications.contains(event.target)) document.getElementById('adminNotifPanel').classList.remove('open'); const profile = document.getElementById('tbProfileWrap'); if (profile && !profile.contains(event.target)) document.getElementById('tbDropdown').classList.remove('open'); });
document.addEventListener('DOMContentLoaded', applyReadState);
setInterval(() => { loadChatContacts(); if (activeChat) loadMessages(); }, 10000);
document.querySelectorAll('.modal-layer').forEach(layer => layer.addEventListener('click', event => { if (event.target === layer) layer.classList.remove('open'); }));
loadHolidays();
</script>
</body>
</html>